ntities($vo['num']); ?></td> --><td class='text-left nowrap'><?php echo htmlentities($vo['commission']); ?></td><td class='text-left nowrap'>冻结：<?php echo htmlentities($vo['user_freeze_balance']); ?><br><p style="color: red;">当前余额：<?php echo htmlentities($vo['balance']); ?></p></td><!-- <td class='text-left nowrap'><?php echo htmlentities($vo['user_freeze_balance']); ?></td> --><td class='text-left nowrap'><?php echo htmlentities($vo['title']); ?><br><p style="color: rgb(89, 0, 255);"><?php echo htmlentities($vo['group_rule_num']); ?>/<?php echo htmlentities($vo['order_num']); ?>（<?php echo htmlentities($vo['group_rule_num_num']); ?>/<?php echo htmlentities($vo['group_rule_num_size']); ?>）</p></td><td class='text-left nowrap'><?php echo htmlentities(format_datetime($vo['addtime'])); ?><br><?php echo htmlentities((format_datetime($vo['pay_time']) ?: '-')); ?></td><td class='text-left nowrap'><?php echo htmlentities(format_datetime($vo['endtime'])); ?></td><td><?php switch($vo['is_pay']): case "0": ?><a class="layui-btn layui-btn-xs layui-btn-primary">未付款</a><?php break; case "1": ?><a class="layui-btn layui-btn-xs">已付款</a><?php break; ?><?php endswitch; ?></td><td class='text-left nowrap'><?php switch($vo['status']): case "0": ?>等待付款<?php break; case "1": ?>完成付款<?php break; case "2": ?>用户取消<?php break; case "3": ?>强制付款<?php break; case "4": ?>系统取消<?php break; case "5": ?>订单冻结<?php break; ?><?php endswitch; ?></td><td class='text-left nowrap'><?php if($vo['status']==0): ?><a data-csrf="<?php echo systoken('order_status'); ?>" class="layui-btn layui-btn-xs layui-btn-danger"
